"use strict";(self.webpackChunk_repo_brand=self.webpackChunk_repo_brand||[]).push([[277],{"./stories/guide/10-social.mdx"(__unused_webpack_module,__webpack_exports__,__webpack_require__){__webpack_require__.r(__webpack_exports__),__webpack_require__.d(__webpack_exports__,{default:()=>MDXContent});__webpack_require__("../../node_modules/next/dist/compiled/react/index.js");var jsx_runtime=__webpack_require__("../../node_modules/next/dist/compiled/react/jsx-runtime.js"),lib=__webpack_require__("../../node_modules/@mdx-js/react/lib/index.js"),blocks=__webpack_require__("../../node_modules/@storybook/addon-docs/dist/blocks.js");function _createMdxContent(props){return(0,jsx_runtime.jsxs)(jsx_runtime.Fragment,{children:[(0,jsx_runtime.jsx)(blocks.W8,{title:"Guide/Social and print"}),"\n",(0,jsx_runtime.jsx)(blocks.oz,{children:"# Social and print\n\n## Posts and print\n\nOne idea per post, in one language. The headline does the work; nothing sits above it. The files are in Social; the printables in Print.\n\n**Posts (1080 × 1350)**\n\n- English posts carry the English lockup; Arabic posts the Arabic lockup, mirrored. Post them separately.\n- The lockup at the top start; two to five words with a full stop in Light, one italic word at most; one sentence; the date or link and @auibsal at the bottom start.\n- Grounds by purpose: crimson for calls and moments, white for events, ink for words worth keeping and recruiting.\n- Photo posts: the picture above (1080 × 820), the words on a solid ink or white panel, the lockup at the bottom end. Never type over a photograph.\n- Instagram crops the grid to 3:4: keep words 80 px from the side edges.\n\n**Print**\n\n- Posters A3/A4: lockup, Light headline, a QR code at the bottom end.\n- Term Card: A6, four to an A4 sheet. Membership cards: 85 × 55 mm.\n- Certificates: A4 landscape, one hairline frame and the lockup.\n- Signage and banners may use the bilingual lockup.\n\n## Carousels and stories\n\nA carousel reads as one piece, in one language and on one ground. A story is a post set for a tall screen.\n\n- **Cover:** a post, and the only slide with the logo.\n- **Inside slides:** a large Light number (\"01\") in accent, a short title with a full stop, one to three lines.\n- **The last slide:** the wordmark alone, in the carousel's language. No symbol, no text, no handle.\n- No slide counters and no \"swipe\" prompts: Instagram shows the dots. Six slides or fewer; ten at most.\n- **Stories, 1080 × 1920:** every word at least 250 px from the top and 340 px from the bottom, clear of the app's own bars; the space under the sentence is left for a link sticker.\n\n## Profile pictures\n\nOne picture per place, so members always know where they are. The Bookmark for the Society, the hoopoe for the bot.\n\n| Place | Picture | File |\n| --- | --- | --- |\n| Instagram and the members' group | The Bookmark in white on crimson | `sal-avatar.svg` |\n| The Diwan group, the officers' working group | The Bookmark in white on ink | `sal-avatar-ink.svg` |\n| Hudhud, the bot (@auibsal_bot) | The hoopoe | `hudhud-avatar.png` |\n\n- The crimson and ink pictures share one shape, so both read as the Society's; the ground tells the members' group from the working group at a glance.\n- Never put the hoopoe on a Society account, or the Bookmark on the bot.\n- Upload the SVGs exported at 1080 × 1080; the circle crop keeps the whole Bookmark.\n\n## Instagram, @auibsal\n\n- **Name:** AUIB Society of Arts and Letters.\n- **Bio:** \"Qirtas, our paper. The Company, our theater. Six programs at @auibaghdad.\"\n- **Links, in this order:** auibsal.org, auibsal.org/events, auibsal.org/join.\n- **Highlights, in this order:** What's on, Qirtas, Next Stop, Programs, Join, Get involved.\n\n## Highlights\n\nSix highlights, each opened by a banner that says what is inside. Covers carry an icon and a name; the banners do the explaining.\n\n- **Covers:** plain crimson with the highlight's icon above its name, both in white (the name in Ubuntu Light), inside the middle 760 px of a 1080 × 1080 square. No Bookmark, no other text.\n- **Banners:** the first story in each highlight, 1080 × 1920 on white. The wordmark alone at the top (no Bookmark), a Light headline with one italic crimson word, one short line, a list split by thin rules, and the link at the bottom.\n- Keep every word 250 px from the top and 340 px from the bottom. Put Instagram's link sticker over the written link.\n- Refresh What's on each term and Qirtas each Edition.\n"})]})}function MDXContent(props={}){const{wrapper:MDXLayout}={...(0,lib.R)(),...props.components};return MDXLayout?(0,jsx_runtime.jsx)(MDXLayout,{...props,children:(0,jsx_runtime.jsx)(_createMdxContent,{...props})}):_createMdxContent()}}}]);
